import{e as a,ab as t,a1 as n,m as o,r as i,p as s}from"./chunks/framework.BGh0NSIy.js";const b=JSON.parse('{"title":"Monthly Updates [May]","description":"May 2026 updates.","frontmatter":{"title":"Monthly Updates [May]","description":"May 2026 updates.","date":"2026-05-01T00:00:00.000Z","next":false,"prev":false,"footer":true},"headers":[],"relativePath":"posts/may-2026.md","filePath":"posts/may-2026.md"}'),l={name:"posts/may-2026.md"};function h(p,e,d,f,g,m){const r=t("Post");return n(),o("div",null,[i(r,{authors:"nbats"}),e[0]||(e[0]=s('<div class="info custom-block"><p class="custom-block-title">INFO</p><p>These update threads only contain major updates. If you&#39;re interested in seeing all minor changes you can follow our <a href="https://github.com/fmhy/FMHYedit/commits/main" target="_blank" rel="noreferrer">Commits Page</a> on GitHub or <a href="https://redd.it/17f8msf" target="_blank" rel="noreferrer">Updates Channel</a> in Discord.</p></div><h1 id="wiki-updates" tabindex="-1">Wiki Updates <a class="header-anchor" href="#wiki-updates" aria-label="Permalink to &quot;Wiki Updates&quot;">​</a></h1><ul><li><p>Added new section for <strong><a href="https://fmhy.net/gaming#indie-games" target="_blank" rel="noreferrer">Indie Games</a></strong> to Special Interest.</p></li><li><p>Added new section for <strong><a href="https://fmhy.net/educational#constructed-languages" target="_blank" rel="noreferrer">Constructed Languages</a></strong> to Language Learning, thank you to @leitzentrale for the idea + sites.</p></li><li><p>Added new section for <strong><a href="https://fmhy.net/mobile#android-rss-readers" target="_blank" rel="noreferrer">Android RSS Readers</a></strong>, thank you to @Waflenoob for doing this.</p></li><li><p>Added Platform Icons + Improved Descriptions in <a href="https://fmhy.net/audio#audio-players" target="_blank" rel="noreferrer">Audio Players</a>, thank you to @RansomQ for doing this. <a href="https://i.ibb.co/MxnwY5Yt/audplayers.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/q9IJXIR.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Added Platform Icons + Improved Descriptions in <a href="https://fmhy.net/file-tools#file-transfer" target="_blank" rel="noreferrer">File Transfer</a> section, thank you to @znarfm for doing this. <a href="https://i.ibb.co/4Rt25wMS/filetransfer.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/GSz3P57.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Added Platform Icons + Improved Descriptions in <a href="https://fmhy.net/system-tools#hardware-monitors" target="_blank" rel="noreferrer">Hardware Monitors</a> section, thank you to @RansomQ for doing this. <a href="https://i.ibb.co/dsPRb17p/hardware.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/b5vidzY.png" target="_blank" rel="noreferrer">2</a>.</p></li><li><p>Added Platform Icons to <a href="https://fmhy.net/file-tools#download-managers" target="_blank" rel="noreferrer">Download Managers</a>, thank you to @RansomQ for doing this. <a href="https://i.ibb.co/WWLym8RC/ddlmanagers.png" target="_blank" rel="noreferrer">Before vs After</a> / <a href="https://i.imgur.com/xUOZhi3.png" target="_blank" rel="noreferrer">2</a>.</p></li></ul><hr><h1 id="stars-added-⭐" tabindex="-1">Stars Added ⭐ <a class="header-anchor" href="#stars-added-⭐" aria-label="Permalink to &quot;Stars Added ⭐&quot;">​</a></h1><ul><li><p>Starred <a href="https://fmhy.net/system-tools#wallpapers" target="_blank" rel="noreferrer">WallWidgy</a> in Wallpapers, minimalist wallpaper collection that people seem to really like, has options for both desktop + mobile.</p></li><li><p>Starred <a href="https://fmhy.net/reading#pdf-search" target="_blank" rel="noreferrer">OceanofPDF</a> in PDF Search, big library, fast downloads, allows users to request books they&#39;re missing.</p></li><li><p>Starred <a href="https://fmhy.net/video#anime-streaming" target="_blank" rel="noreferrer">Animetsu</a> in Anime Streaming, very fast servers, has auto-play / auto-next and clean interface.</p></li><li><p>Starred both <a href="https://fmhy.net/reading#manga" target="_blank" rel="noreferrer">Mangadot + OniSaga</a> in Manga Sites, both have impressive UIs, big libraries, and nice features.</p></li><li><p>Starred <a href="https://fmhy.net/privacy#privacy-indexes" target="_blank" rel="noreferrer">Awesome Privacy</a> in Privacy Indexes, collection of privacy focused alternatives with a nice UI.</p></li><li><p>Starred <a href="https://fmhy.net/misc#physical-health" target="_blank" rel="noreferrer">Insomnia Guide</a> in Physical Health, in depth, cites all sources, has been well received by people.</p></li><li><p>Starred <a href="https://fmhy.net/audio#music-discovery" target="_blank" rel="noreferrer">RYM Charts</a> in Music Discovery. We do already have RYM starred under tracking sites, but its customizable charts also make it one of the best ways to discover new music. You can create <a href="https://i.ibb.co/Ft5NNJJ/image.png" target="_blank" rel="noreferrer">as many charts</a> / <a href="https://i.imgur.com/dsT6H2V.png" target="_blank" rel="noreferrer">2</a> as you want with very in-depth filtering options.</p></li><li><p>Starred <a href="https://fmhy.net/audio#concerts-live-shows" target="_blank" rel="noreferrer">bootleg.fm</a> in Concerts / Live Shows, community driven archive of bootleg concert recording, well organized, covers lots of artists, and is being actively developed.</p></li><li><p>Starred <a href="https://fmhy.net/storage#svg-icons" target="_blank" rel="noreferrer">SVGL</a> in SVG Icons, nice library of SVG company + program icons, seems to be well liked by people.</p></li><li><p>Starred <a href="https://fmhy.net/educational#language-learning" target="_blank" rel="noreferrer">Omniglot</a> in Language Learning, in depth encyclopedia of writing systems and languages.</p></li><li><p>Starred <a href="https://fmhy.net/mobile#social-media-apps-1" target="_blank" rel="noreferrer">Swiftgram</a> in iOS Social Media Apps, feature-rich Telegram client, open-source, and available on official Apple app store.</p></li><li><p>Starred <a href="https://fmhy.net/misc#shopping" target="_blank" rel="noreferrer">Fragrantica</a> in shopping section, comprehensive fragrance database, visualizations, user voting, collection tracking and more.</p></li><li><p>Starred <a href="https://fmhy.net/text-tools#free-fonts" target="_blank" rel="noreferrer">wFonts</a> in Free Fonts, nice UI, huge library, labels any potential licenses.</p></li><li><p>Moved AB Download Manager to #1 Download manager as its open-source and works just as well (or better in some cases) than jdownloader.</p></li></ul><hr><h1 id="things-removed" tabindex="-1">Things Removed <a class="header-anchor" href="#things-removed" aria-label="Permalink to &quot;Things Removed&quot;">​</a></h1><ul><li><p>Removed GenP as they are <a href="https://i.ibb.co/yFqkGHp1/image.png" target="_blank" rel="noreferrer">stepping down</a> / <a href="https://i.imgur.com/4B2QKCa.png" target="_blank" rel="noreferrer">2</a>. Thank you to their team for all the years of hard work.</p></li><li><p>Removed Myrient as its <a href="https://i.ibb.co/pB0My03B/image.png" target="_blank" rel="noreferrer">officially closed now</a> / <a href="https://i.imgur.com/9g3x9Ad.png" target="_blank" rel="noreferrer">2</a>. Rest in peace, it will be sorely missed. Thank you to their team for running it for so long.</p></li><li><p>Removed NekoGram + added to our unsafe list as it seems they were transmitting peoples account-phone numbers to one of their TG bots via <a href="https://x.com/sotanews/status/2039652946233688273" target="_blank" rel="noreferrer">a hidden backdoor</a> / <a href="https://thebadinteger.github.io/nekogram-phone-exfiltration/" target="_blank" rel="noreferrer">2</a>. Their devs are claiming they had no malicious intention, but the situation is sketchy so we&#39;re erring on the side of caution for now.</p></li><li><p>Removed BlockTheSpot as its been archived.</p></li><li><p>Removed both Soft98 + DownloadHa as no one can get either to work anymore. We&#39;ll keep an eye on them and re-add if either ever starts working again in the future.</p></li><li><p>Sunset the FMHY FreshRSS instance as <a href="https://i.ibb.co/ymgS7b6n/image.png" target="_blank" rel="noreferrer">we&#39;re no longer able</a> / <a href="https://i.imgur.com/yd95YDd.png" target="_blank" rel="noreferrer">2</a> to run it anymore sadly. It will be shut down May 1st.</p></li><li><p>Unstarred Grok in Official Model Sites since its limits have been getting worse for free users (they are trying to push users towards paid plans) and they are actively blocking many email domain names including those used for temp mail. They have also taken features away and downgraded the versions of models free users get (you used to get 4 expert 4.20, now you get 1 expert 4.20). (from kiri)</p></li><li><p>Unstarred Arena as they&#39;ve <a href="https://i.ibb.co/rfLx1jFT/image.png" target="_blank" rel="noreferrer">removed some of their better models</a> / <a href="https://i.imgur.com/4Q1zv3m.png" target="_blank" rel="noreferrer">2</a>.</p></li></ul>',9))])}const u=a(l,[["render",h]]);export{b as __pageData,u as default};
